"""
CLI entry point for the Simulation Agent system.

Usage:
    python -m simulation_agent.main "Complete 300 sites in Chicago in 2 weeks"
    python -m simulation_agent.main --interactive
"""
from __future__ import annotations

import sys
import json
import logging
import argparse
from datetime import datetime

from graph import run_simulation
from tools.neo4j_tool import neo4j_tool
from fastapi import FastAPI
import uvicorn
from fastapi.middleware.cors import CORSMiddleware


# ── Logging setup ──
# force=True ensures we replace any handlers uvicorn already attached,
# preventing duplicate log lines when running under uvicorn --reload.
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s │ %(name)-30s │ %(levelname)-5s │ %(message)s",
    datefmt="%H:%M:%S",
    force=True,
)
logger = logging.getLogger(__name__)

# Suppress verbose HTTP request logs from httpx (e.g. OpenAI API calls)
logging.getLogger("httpx").setLevel(logging.WARNING)
logging.getLogger("httpcore").setLevel(logging.WARNING)


"""
FastAPI application factory.

Creates the app, registers middleware, and mounts versioned routers.
No business logic lives here.

Run:
    uvicorn api.app:app --reload --port 8000

Swagger UI:  http://localhost:8000/docs
ReDoc:       http://localhost:8000/redoc
"""
from contextlib import asynccontextmanager
from pathlib import Path
from fastapi.responses import FileResponse
from api.v1.router import router as v1_router
import services.db_service as db_svc


@asynccontextmanager
async def lifespan(app: FastAPI):
    db_svc.ensure_tables()
    yield
    db_svc.close_pool()


app = FastAPI(
    lifespan=lifespan,
    title="Simulation Agent API",
    description=(
        "LangGraph multi-agent system backed by Neo4j (BKG) and PostgreSQL.\n\n"
    ),
    version="1.0.0",
)

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_methods=["*"],
    allow_headers=["*"],
)

@app.get("/", tags=["Root"])
async def root():
    return{
        "service": "Simulator service",
        "version": "1.0.0",
        "docs": "/docs"
    }

app.include_router(v1_router, prefix="/api")


@app.get("/bkg-admin", tags=["BKG Admin UI"], include_in_schema=False)
async def bkg_admin_ui():
    """Serve the single-page BKG admin interface."""
    html_path = Path(__file__).parent / "static" / "bkg_admin.html"
    return FileResponse(html_path)

if __name__ == "__main__":
    import os

    reload = os.getenv("RELOAD", "false").lower() == "true"
    workers = int(os.getenv("WORKERS", "1"))

    # NOTE: Using workers > 1 requires replacing MemorySaver with a
    # persistent checkpointer (e.g. PostgresSaver) so HITL state is
    # shared across worker processes.  Keep workers=1 until that migration.
    uvicorn.run(
        "main:app",
        host="0.0.0.0",
        port=8000,
        reload=reload,
        workers=1 if reload else workers,
    )

# tep 1: `Swap/Construction Completion Rate` — change planned anchor from pj_p_5175_construction_complete_finish to pj_p_4225_construction_start_finish
# MATCH (n:BKGNode {session_id: '69a3d22f26e208edc083a06e', node_id: '74904211-c4aa-48c0-a998-aaf0ab9d58cb'})
# SET
#     n.kpi_business_logic = '1) Source: pwc_macro_staging_schema.stg_ndpd_mbt_tmobile_macro_combined; no JOIN. 2) Excludes Dead projects: COALESCE(pj_project_status, \'\') <> \'Dead\'. 3) Optional equality filters: rgn_region, m_area, m_market, construction_gc, pj_project_id, s_site_id, customer_site_code, smp_id, por_category. 4) smp_name conditional: when \'NTM\', also enforce smp_status=\'Active\' and exclude ntm_project_type IN (\'E2E06 - NSD Cx Mgmt\', \'E2E07 - OL/MOD Cx Mgmt\'). 5) Optional date range (start_date / end_date) applies to pj_a_5175_construction_complete_finish and restricts ONLY the completed_count, completion_rate_pct, gap and on-time aggregates; total_sites and pending_count remain unfiltered so the rate stays meaningful. 6) CTE base: per-project actual_date = pj_a_5175_construction_complete_finish, planned_date = pj_p_4225_construction_start_finish, gap_days = actual_date::date - planned_date::date (NULL when either is missing), delay_reason = pj_construction_complete_delay_code (surfaced as a GROUP BY dimension). 7) Aggregate per (rgn_region, m_area, m_market, construction_gc, delay_reason): total_sites = COUNT(DISTINCT pj_project_id); completed_count = COUNT(DISTINCT projects with actual_date NOT NULL); pending_count = COUNT(DISTINCT projects with actual_date NULL); completion_rate_pct = ROUND(100.0 * completed_count / NULLIF(total_sites, 0), 2); avg_gap_days = ROUND(AVG(gap_days)::numeric, 0); max_gap_days = MAX(gap_days); on_time_count = COUNT(DISTINCT projects with gap_days <= 0); delayed_count = COUNT(DISTINCT projects with gap_days > 0); on_time_pct = ROUND(100.0 * on_time_count / NULLIF(on_time_count + delayed_count, 0), 2).',
