#     n.kpi_python_function = 'def get_swap_construction_completion_rate(execute_query, filters=None) -> list[dict]:\n    """Swap/Construction Completion Rate — per (geo, GC, delay reason).\n\n    actual_date  = pj_a_5175_construction_complete_finish\n    planned_date = pj_p_4225_construction_start_finish\n    gap_days     = actual_date::date - planned_date::date  (when both present)\n\n    Population:\n      - Excludes Dead projects (COALESCE(pj_project_status, \'\') <> \'Dead\').\n      - smp_name = \'NTM\' → also enforces smp_status=\'Active\' and excludes specific\n        ntm_project_type values.\n\n    Optional generic equality filters: rgn_region, m_area, m_market, construction_gc,\n    pj_project_id, s_site_id, customer_site_code, smp_name, smp_id, por_category.\n\n    Optional date range: start_date / end_date apply to actual_date and restrict ONLY\n    the completed_count / completion_rate / gap / on-time counters; total_sites and\n    pending_count are NOT date-filtered so completion % stays meaningful.\n\n    Output (one row per (rgn_region, m_area, m_market, construction_gc, delay_reason)):\n      total_sites, completed_count, pending_count, completion_rate_pct,\n      avg_gap_days (ROUND to 0), max_gap_days, on_time_count, delayed_count, on_time_pct.\n    """\n    filters = filters or {}\n\n    def _esc(v):\n        return str(v).replace("\'", "\'\'")\n\n    where_parts = ["COALESCE(\\"pj_project_status\\", \'\') <> \'Dead\'"]\n\n    optional_eq_cols = [\n        "rgn_region", "m_area", "m_market", "construction_gc",\n        "pj_project_id", "s_site_id", "customer_site_code",\n        "smp_id", "por_category",\n    ]\n    for col in optional_eq_cols:\n        v = filters.get(col)\n        if v is not None and str(v) != "":\n            where_parts.append(f\'"{col}" = \\\'{_esc(v)}\\\'\')\n\n    smp_name = filters.get("smp_name")\n    if smp_name is not None and str(smp_name).strip() != "":\n        v = _esc(smp_name)\n        where_parts.append(f\'"smp_name" = \\\'{v}\\\'\')\n        if str(smp_name).strip().upper() == \'NTM\':\n            where_parts.append(\'"smp_status" = \\\'Active\\\'\')\n            where_parts.append(\'"ntm_project_type" NOT IN (\\\'E2E06 - NSD Cx Mgmt\\\', \\\'E2E07 - OL/MOD Cx Mgmt\\\')\')\n\n    where_sql = " AND ".join(where_parts)\n\n    # Date range applies to actual_date — restricts only the "completed" measurements,\n    # keeping total_sites and pending_count unfiltered so the rate stays meaningful.\n    completed_extra = ""\n    start_date = filters.get("start_date")\n    end_date = filters.get("end_date")\n    if start_date:\n        completed_extra += f" AND actual_date::date >= DATE \'{_esc(start_date)}\'"\n    if end_date:\n        completed_extra += f" AND actual_date::date <= DATE \'{_esc(end_date)}\'"\n\n    sql = f"""\n        WITH base AS (\n            SELECT\n                "rgn_region",\n                "m_area",\n                "m_market",\n                "construction_gc",\n                "pj_construction_complete_delay_code" AS delay_reason,\n                "pj_project_id",\n                "pj_a_5175_construction_complete_finish" AS actual_date,\n                "pj_p_4225_construction_start_finish" AS planned_date,\n                CASE\n                    WHEN "pj_a_5175_construction_complete_finish" IS NOT NULL\n                     AND "pj_p_4225_construction_start_finish" IS NOT NULL\n                    THEN "pj_a_5175_construction_complete_finish"::date\n                       - "pj_p_4225_construction_start_finish"::date\n                END AS gap_days\n            FROM pwc_macro_staging_schema.stg_ndpd_mbt_tmobile_macro_combined\n            WHERE {where_sql}\n        )\n        SELECT\n            "rgn_region",\n            "m_area",\n            "m_market",\n            "construction_gc",\n            delay_reason,\n            COUNT(DISTINCT "pj_project_id") AS total_sites,\n            COUNT(DISTINCT CASE\n                WHEN actual_date IS NOT NULL{completed_extra}\n                THEN "pj_project_id"\n            END) AS completed_count,\n            COUNT(DISTINCT CASE\n                WHEN actual_date IS NULL\n                THEN "pj_project_id"\n            END) AS pending_count,\n            ROUND(\n                100.0 * COUNT(DISTINCT CASE\n                    WHEN actual_date IS NOT NULL{completed_extra}\n                    THEN "pj_project_id"\n                END) / NULLIF(COUNT(DISTINCT "pj_project_id"), 0),\n                2\n            ) AS completion_rate_pct,\n            ROUND(AVG(CASE WHEN gap_days IS NOT NULL{completed_extra} THEN gap_days END)::numeric, 0) AS avg_gap_days,\n            MAX(CASE WHEN gap_days IS NOT NULL{completed_extra} THEN gap_days END) AS max_gap_days,\n            COUNT(DISTINCT CASE\n                WHEN gap_days IS NOT NULL AND gap_days <= 0{completed_extra}\n                THEN "pj_project_id"\n            END) AS on_time_count,\n            COUNT(DISTINCT CASE\n                WHEN gap_days IS NOT NULL AND gap_days > 0{completed_extra}\n                THEN "pj_project_id"\n            END) AS delayed_count,\n            ROUND(\n                100.0 * COUNT(DISTINCT CASE\n                    WHEN gap_days IS NOT NULL AND gap_days <= 0{completed_extra}\n                    THEN "pj_project_id"\n                END) / NULLIF(COUNT(DISTINCT CASE\n                    WHEN gap_days IS NOT NULL{completed_extra}\n                    THEN "pj_project_id"\n                END), 0),\n                2\n            ) AS on_time_pct\n        FROM base\n        GROUP BY "rgn_region", "m_area", "m_market", "construction_gc", delay_reason\n        ORDER BY "rgn_region", "m_area", "m_market", "construction_gc", delay_reason\n    """\n\n    return execute_query(sql)\n',
#     n.kpi_source_columns = ['pj_project_status', 'rgn_region', 'm_area', 'm_market', 'construction_gc', 'pj_project_id', 'por_category', 's_site_id', 'customer_site_code', 'smp_name', 'smp_status', 'smp_id', 'ntm_project_type', 'pj_a_5175_construction_complete_finish', 'pj_p_4225_construction_start_finish', 'pj_construction_complete_delay_code']
