# Step 2: `Construction Plan Forecast` — change GC run-rate column from ms_1555_construction_complete_actual to pj_a_5175_construction_complete_finish
# MATCH (n:BKGNode {session_id: '69a3d22f26e208edc083a06e', node_id: 'cpf-001-construction-plan-forecast'})
# SET
#     n.kpi_business_logic = '1) Committed pool: sites where pj_p_4225_construction_start_finish in [today, today+window_days] and ms_1550_construction_start_actual IS NULL. Bucket by ISO-week of pj_p_4225. 2) Pull-forward pool: sites where pj_p_4225 > today+window_days, not already started, and prereq_pct >= threshold. Bucket by ISO-week of forecasted Cx-ready date (NOT gated on forecast <= window). 3) prereq_pct per site = done_gates / applicable_gates, using the gate list inherited from the Prereq Readiness Rate KPI (dcf98a0e-...), with: Crane applicable only when scoping_package_crane_required = \'Yes\'; Crane done when scoping_package_crane_required IN (\'Yes\',\'No\'). 4) Forecasted Cx-ready date = (latest populated pj_a_*/ms_* among applicable+done gates) + shortest-path remaining SLA days to Cx Start, computed over kpi_sla_dag. 5) GC run-rate capacity: count rows with pj_a_5175_construction_complete_finish in [today-60d, today], divide by 8 -> weekly cap. Flag weekly buckets where committed+pull_forward > cap.',
#     n.kpi_python_function = '# Construction Plan Forecast — build_plan(target_sites, window_days, prereq_threshold,\n#                                         project_type, sla_dag, execute_query)\n# Convention: uses the sandbox-provided execute_query(sql) -> list[dict] (NOT raw cur).\n# Site identifier: s_site_id (per traversal rule; NEVER pj_project_id for site counts).\n\nfrom datetime import date, timedelta\nfrom collections import deque, defaultdict\n\ndef _applicable_nodes(sla_dag_pt, site_row):\n    """Per-site applicable gate set. Honors `applicability_when` on any node spec —\n    currently used for crane_readiness (only applicable when site needs a crane)."""\n    applicable = set()\n    for name, spec in sla_dag_pt.items():\n        if name in ("JOIN", "cx_start"):\n            continue\n        appl_when = spec.get("applicability_when")\n        if appl_when:\n            val = site_row.get(spec.get("column"))\n            if val not in appl_when:\n                continue\n        applicable.add(name)\n    return applicable\n\ndef _is_done(node_name, spec, site_row):\n    """Gate-completion rule, dispatched on `kind`:\n        - "flag" (Yes/No / status flag): done when value in spec["done_when"]\n        - "id"   (non-date identifier):  done when value is not null\n        - "date" (default):              done when column has a non-null value\n                                         (after SQL ::date cast, that value IS a date)\n    """\n    col = spec.get("column")\n    alt = spec.get("alt_column")\n    kind = spec.get("kind", "date")\n    val = site_row.get(col) if col else None\n    if kind == "flag":\n        return val in (spec.get("done_when") or [])\n    # date / id — gate done when column has any non-null value\n    if val is not None:\n        return True\n    if alt and site_row.get(alt) is not None:\n        return True\n    return False\n\ndef _last_completed_milestone(applicable, sla_dag_pt, site_row):\n    """Only date-kind milestones can be the \'last completed\' anchor — id/flag\n    gates have no date for the forecast to walk forward from."""\n    best_name, best_date = None, None\n    for name in applicable:\n        spec = sla_dag_pt[name]\n        if spec.get("kind", "date") != "date":\n            continue\n        if not _is_done(name, spec, site_row):\n            continue\n        d = site_row.get(spec.get("column")) or site_row.get(spec.get("alt_column"))\n        if d and (best_date is None or d > best_date):\n            best_name, best_date = name, d\n    return best_name, best_date\n\ndef _shortest_path_days(sla_dag_pt, start, applicable):\n    if start is None or start == "cx_start":\n        return 0\n    visited = {start: 0}\n    q = deque([start])\n    while q:\n        u = q.popleft()\n        for v, w in (sla_dag_pt.get(u, {}).get("edges") or {}).items():\n            if v not in ("JOIN", "cx_start") and v not in applicable:\n                continue\n            nd = visited[u] + (w or 0)\n            if v not in visited or nd < visited[v]:\n                visited[v] = nd\n                q.append(v)\n    return visited.get("cx_start")\n\ndef _iso_week_start(d):\n    return d - timedelta(days=d.weekday())\n\ndef _to_date(v):\n    """Normalize any DB / pandas date-ish value to datetime.date | None.\n\n    Handles every shape produced by execute_query (which uses pd.read_sql):\n      - None                            -> None\n      - pandas NaT / nan                -> None\n      - datetime.datetime               -> v.date()    (datetime IS a subclass of date,\n                                                        so must be checked BEFORE \'date\')\n      - pandas.Timestamp                -> v.date()\n      - datetime.date                   -> v\n      - ISO string "YYYY-MM-DD..."      -> date.fromisoformat(s[:10])\n      - anything else                   -> None\n    Without this, comparisons later raise: \'Cannot compare Timestamp with datetime.date\',\n    \'Cannot compare NaT\', or "\'>\' not supported between str and date".\n    """\n    if v is None:\n        return None\n    # pandas NaT / nan — check BEFORE the date isinstance below.\n    try:\n        import pandas as _pd\n        if _pd.isna(v):\n            return None\n    except Exception:\n        pass\n    # datetime.datetime is a subclass of date — strip the time part.\n    try:\n        from datetime import datetime as _dt\n        if isinstance(v, _dt):\n            return v.date()\n    except Exception:\n        pass\n    # pandas.Timestamp and similar wrappers expose .date() returning a date.\n    d_attr = getattr(v, "date", None)\n    if callable(d_attr):\n        try:\n            d = d_attr()\n            if isinstance(d, date):\n                return d\n        except Exception:\n            pass\n    if isinstance(v, date):\n        return v\n    # Strings — ISO date or ISO timestamp prefix.\n    try:\n        return date.fromisoformat(str(v)[:10])\n    except Exception:\n        return None\n\n_FILTERABLE_COLUMNS = (\n    "rgn_region", "m_area", "m_market", "construction_gc",\n    "por_category", "pj_project_status", "s_site_class", "smp_name",\n)\n\ndef _filter_clause(filters):\n    """Build \' AND col = \'\'val\'\' \' fragments from a user-supplied filter dict.\n    Supports scalar equality and list-of-values (IN). Unknown keys are ignored\n    so the LLM cannot inject arbitrary columns."""\n    if not filters:\n        return ""\n    parts = []\n    for k, v in filters.items():\n        if v is None or k not in _FILTERABLE_COLUMNS:\n            continue\n        if isinstance(v, (list, tuple, set)):\n            vals = [str(x).replace("\'", "\'\'") for x in v if x is not None]\n            if vals:\n                parts.append(k + " IN (" + ", ".join("\'" + x + "\'" for x in vals) + ")")\n        else:\n            parts.append(k + " = \'" + str(v).replace("\'", "\'\'") + "\'")\n    return (" AND " + " AND ".join(parts)) if parts else ""\n\ndef build_plan(target_sites, window_days=60, prereq_threshold=0.80,\n               project_type="NTM", sla_dag=None, execute_query=None,\n               filters=None, split_on_gate=None,\n               mobilization_buffer_days=10,\n               pull_forward_lookup_days=None):\n    """Forecast a week-by-week construction-start plan.\n\n    filters: optional dict to scope the plan and the GC run-rate to a slice of the\n    portfolio. Supported keys (any subset; equality or list-of-values):\n        rgn_region, m_area, m_market, construction_gc,\n        por_category, pj_project_status, s_site_class, smp_name\n    Example: {"rgn_region": "SOUTH", "construction_gc": "GC-X"}\n    Unknown keys are silently dropped (the LLM cannot inject arbitrary columns).\n\n    split_on_gate: optional gate name from the SLA DAG (e.g. "cpo", "ntp",\n    "material_picked"). When set, the algorithm partitions sites into two\n    cohorts — one where that gate is DONE, one where it\'s MISSING — and runs\n    the committed/pull-forward/weekly-bucket computation for each cohort.\n    Use this for queries that name a specific milestone condition like\n    "plan 500 sites; 300 have PO missing". Returns:\n        {"cohorts": {"<gate>_done": {...}, "<gate>_missing": {...}}, "capacity": ..., "config": ...}\n    Default is None — single-cohort behavior, returns the flat shape.\n\n    pull_forward_lookup_days: optional upper bound on how far into the future\n    to search for pull-forward candidates. When set to N, candidates must\n    have planned_cx within [horizon, today + N days]; sites planned beyond\n    that are excluded even if their prereq_pct ≥ threshold. When None\n    (default), there is no upper bound — the prereq_threshold (80% default)\n    is the only filter, so very-far-future sites with mostly-done pre-reqs\n    still qualify. Set this only when the user explicitly states a search\n    horizon distinct from the committed window (e.g. "plan 500 in next 2\n    months but only consider sites planned within 6 months").\n    """\n    assert sla_dag is not None, "sla_dag must be passed (from kpi_sla_dag node property)"\n    assert execute_query is not None, "execute_query helper must be passed in"\n    pt = sla_dag[project_type]\n    today = date.today()\n    horizon = today + timedelta(days=window_days)\n    # Earliest realistically-plannable Monday.\n    # Semantics: "plan can START after the mobilization buffer ends."\n    #   buffered_date = today + mobilization_buffer_days   # earliest day work can happen\n    #   earliest_start_monday = first Monday strictly on-or-AFTER buffered_date\n    # This guarantees:\n    #   (a) The Monday is never in the past (buffered_date >= today, so its\n    #       next-Monday >= today\'s next Monday).\n    #   (b) The Monday never overlaps the mobilization period — Week 1 of the\n    #       rendered plan always represents a clean, post-buffer week.\n    #   (c) Weekend buffer dates roll forward naturally (Sat → next Mon).\n    #   (d) Buffer = 0 on a Wednesday gives the next Monday, NOT this week\'s\n    #       (past) Monday.\n    # Buckets that would otherwise fall before this Monday — past-dated stale\n    # forecasts, or committed starts inside the buffer window — roll forward\n    # to this Monday. Raw per-site dates are preserved for transparency.\n    buffered = today + timedelta(days=mobilization_buffer_days)\n    days_to_monday = (7 - buffered.weekday()) % 7   # 0 if buffered is already Mon\n    earliest_start_monday = buffered + timedelta(days=days_to_monday)\n\n    # Optional upper bound on pull-forward candidate search.\n    # None  => no cap (prereq_threshold is the sole filter).\n    # int N => candidates must have planned_cx <= today + N days.\n    pull_forward_horizon = (today + timedelta(days=pull_forward_lookup_days)\n                            if pull_forward_lookup_days is not None else None)\n\n    user_filter = _filter_clause(filters)\n\n    # --- 1. SINGLE SQL FETCH of in-flight sites -----------------------------\n    # Classify each referenced column as date vs non-date so we only cast date\n    # columns. Two of the staging columns (so_header, cpo_custom_field) are\n    # varchar holding identifiers — casting them to ::date would raise. The\n    # crane / 24x7 flag columns are also varchar holding \'Yes\'/\'No\'.\n    date_cols = set()\n    non_date_cols = set()\n    for spec in pt.values():\n        col = spec.get("column")\n        if not col:\n            continue\n        kind = spec.get("kind", "date")\n        if kind == "date":\n            date_cols.add(col)\n            if spec.get("alt_column"):\n                date_cols.add(spec["alt_column"])\n        else:\n            non_date_cols.add(col)\n    # Always-fetched date columns (planned/started/complete on every project)\n    date_cols |= {"pj_p_4225_construction_start_finish",\n                  "ms_1550_construction_start_actual",\n                  "pj_a_5175_construction_complete_finish"}\n    # Always-fetched non-date columns\n    non_date_cols |= {"scoping_package_crane_required", "s_site_id", "smp_name"}\n\n    # --- DEFENSIVE: drop any SLA-DAG-referenced column that does not exist on\n    # this staging table. Different deployments / DAG entries may reference\n    # columns sourced from sibling tables (e.g. AHLOB\'s `nas_activity_end_date`\n    # lives in stg_nas_planned_outage_activity, not the macro_combined table).\n    # Missing columns are silently treated as "gate never done" rather than\n    # crashing the SELECT with \'column does not exist\'. The list of skipped\n    # columns is echoed back in config so the response agent can flag them.\n    schema_rows = execute_query(\n        "SELECT column_name FROM information_schema.columns "\n        "WHERE table_schema = \'pwc_macro_staging_schema\' "\n        "AND table_name = \'stg_ndpd_mbt_tmobile_macro_combined\'"\n    ) or []\n    present = {r["column_name"] for r in schema_rows}\n    skipped_cols = sorted((date_cols | non_date_cols) - present)\n    date_cols     &= present\n    non_date_cols &= present\n    # Build SELECT: defensively cast date columns. Many milestone columns are\n    # stored as VARCHAR in this schema and a small fraction contain non-date\n    # garbage ("onto", "TBD", "N/A", "pending", etc.) that ::date would crash\n    # on. We use a CASE+regex to coerce only well-formed ISO prefixes and\n    # NULL the rest, so one bad row does not abort the whole query. Works for\n    # both VARCHAR and TIMESTAMP columns (coerced to text first).\n    def _safe_date_cast(c):\n        # In Python f-string, doubled braces {{ }} render as literal { } in SQL.\n        return (\n            "CASE WHEN " + c + "::text ~ \'^[0-9]{4}-[0-9]{2}-[0-9]{2}\' "\n            "THEN substring(" + c + "::text, 1, 10)::date ELSE NULL END AS " + c\n        )\n    select_parts = [_safe_date_cast(c) for c in sorted(date_cols)]\n    select_parts += [c for c in sorted(non_date_cols - date_cols)]\n    col_list = ", ".join(select_parts)\n    smp_filter = ""\n    user_set_smp = filters and "smp_name" in filters and filters["smp_name"] is not None\n    if not user_set_smp:\n        # Production DB has exactly two smp_name values: \'NTM\' and \'AHLOB Modernization\'.\n        # Use strict equality (NOT <>/IS NULL fallback) so an NTM plan benchmarks only\n        # against NTM, and an AHLOB plan only against AHLOB Modernization.\n        if project_type == "AHLOB":\n            smp_filter = " AND smp_name = \'AHLOB Modernization\'"\n        elif project_type == "NTM":\n            smp_filter = " AND smp_name = \'NTM\'"\n    fetch_sql = (\n        "SELECT " + col_list +\n        " FROM pwc_macro_staging_schema.stg_ndpd_mbt_tmobile_macro_combined" +\n        " WHERE ms_1550_construction_start_actual IS NULL" +\n        " AND s_site_id IS NOT NULL" +\n        smp_filter +\n        user_filter\n    )\n    rows = execute_query(fetch_sql) or []\n\n    # --- 2. GC RUN-RATE CAPACITY (scoped to the same filter slice — including\n    # the project_type / smp_name filter, so an NTM plan is benchmarked against\n    # NTM completion velocity, not against the AHLOB+NTM combined pool which\n    # has very different critical-path profiles). The completion column uses\n    # the same defensive cast as the main fetch — rows with non-date garbage\n    # ("onto", "TBD", etc.) coerce to NULL and are naturally excluded by the\n    # BETWEEN range, instead of crashing the whole capacity query.\n    cap_sql = (\n        "SELECT COUNT(DISTINCT s_site_id) AS cnt"\n        " FROM pwc_macro_staging_schema.stg_ndpd_mbt_tmobile_macro_combined"\n        " WHERE (CASE WHEN pj_a_5175_construction_complete_finish::text "\n        "~ \'^[0-9]{4}-[0-9]{2}-[0-9]{2}\' "\n        "THEN substring(pj_a_5175_construction_complete_finish::text, 1, 10)::date "\n        "ELSE NULL END) BETWEEN "\n        "\'" + (today - timedelta(days=60)).isoformat() + "\'"\n        " AND \'" + today.isoformat() + "\'" +\n        smp_filter +\n        user_filter\n    )\n    cap_rows = execute_query(cap_sql) or [{"cnt": 0}]\n    completed_last_60d = int(cap_rows[0].get("cnt") or 0)\n    weekly_cap = max(1, completed_last_60d // 8)   # GC run rate per week (filter-scoped)\n\n    # --- 3. NORMALIZE DATES upfront so cohort partition + classification share\n    # the same normalized rows. id/flag columns stay as raw strings — _is_done\n    # dispatches on kind to interpret them correctly.\n    for row in rows:\n        for k in date_cols:\n            if k in row:\n                row[k] = _to_date(row[k])\n\n    # --- 4. PER-COHORT COMPUTE (reusable for the single-cohort path AND for\n    # the split_on_gate path that runs it twice on disjoint subsets) ----------\n    def _compute_cohort(subset_rows):\n        committed_c, pull_forward_c = [], []\n        for row in subset_rows:\n            planned_cx = row.get("pj_p_4225_construction_start_finish")\n            if planned_cx is None:\n                continue\n            applicable = _applicable_nodes(pt, row)\n            done = {n for n in applicable if _is_done(n, pt[n], row)}\n            prereq_pct = (len(done) / len(applicable)) if applicable else 0.0\n            last_ms, last_dt = _last_completed_milestone(applicable, pt, row)\n            remaining = _shortest_path_days(pt, last_ms, applicable)\n            forecast = (last_dt + timedelta(days=remaining)) if (last_dt and remaining is not None) else None\n            if today <= planned_cx <= horizon:\n                committed_c.append({"site_id": row["s_site_id"], "planned_cx": planned_cx,\n                                    "prereq_pct": round(prereq_pct, 2)})\n            elif (planned_cx > horizon and prereq_pct >= prereq_threshold and\n                  (pull_forward_horizon is None or planned_cx <= pull_forward_horizon)):\n                blockers = sorted(applicable - done)\n                # `forecast` may land in the past when the site\'s last completed\n                # milestone is stale (project paused, data not refreshed). The\n                # site is still functionally "ready" — its pre-reqs are done —\n                # so we record BOTH the raw forecast (for transparency / data-\n                # quality flagging) and a bucketing forecast clamped to today.\n                stale_forecast = forecast is not None and forecast < today\n                pull_forward_c.append({"site_id": row["s_site_id"], "planned_cx": planned_cx,\n                                       "forecast_cx_ready":       forecast,\n                                       "forecast_is_stale":       stale_forecast,\n                                       "prereq_pct": round(prereq_pct, 2),\n                                       "last_milestone": last_ms,\n                                       "remaining_sla_days": remaining,\n                                       "blockers": blockers})\n        bk = defaultdict(lambda: {"committed": 0, "pull_forward": 0})\n        for s in committed_c:\n            # Committed sites already on the GC\'s schedule (planned_cx is\n            # in the future per Step 3\'s filter). If planned_cx falls before\n            # earliest_start_monday — i.e. inside the mobilization buffer —\n            # roll the bucket forward so the plan never claims work starts\n            # before crews can realistically mobilize. The site\'s actual\n            # planned_cx is preserved on its per-site record.\n            wk = _iso_week_start(s["planned_cx"])\n            if wk < earliest_start_monday:\n                wk = earliest_start_monday\n            bk[wk]["committed"] += 1\n        for s in pull_forward_c:\n            fr = s["forecast_cx_ready"]\n            if not fr:\n                continue\n            # Same floor for pull-forward: past-dated forecasts (stale data)\n            # AND forecasts inside the mobilization buffer both roll to the\n            # earliest plannable Monday. The raw forecast_cx_ready and the\n            # forecast_is_stale flag stay on the per-site record so the\n            # response can flag data-freshness issues separately.\n            wk = _iso_week_start(fr)\n            if wk < earliest_start_monday:\n                wk = earliest_start_monday\n            bk[wk]["pull_forward"] += 1\n        wb = []\n        for ws in sorted(bk):\n            b = bk[ws]\n            total = b["committed"] + b["pull_forward"]\n            wb.append({"week_start": ws, "committed": b["committed"],\n                       "pull_forward": b["pull_forward"], "total": total,\n                       "capacity_cap": weekly_cap, "over_capacity": total > weekly_cap})\n        stale_count = sum(1 for s in pull_forward_c if s.get("forecast_is_stale"))\n        return {\n            "summary": {"target": target_sites, "window_days": window_days,\n                        "committed_count": len(committed_c),\n                        "pull_forward_count": len(pull_forward_c),\n                        "stale_pull_forward_count": stale_count,\n                        "total_in_window": len(committed_c) + len(pull_forward_c),\n                        "gap_vs_target": target_sites - (len(committed_c) + len(pull_forward_c)),\n                        "cohort_row_count": len(subset_rows)},\n            "weekly_buckets":     wb,\n            "committed_sites":    committed_c,    # per-site detail for Gantt rendering\n            "pull_forward_sites": pull_forward_c,\n        }\n\n    capacity = {"method": "gc_run_rate",\n                "completed_last_60d": completed_last_60d, "weekly_cap": weekly_cap}\n    config = {"prereq_threshold": prereq_threshold, "project_type": project_type,\n              "filters": {k: v for k, v in (filters or {}).items()\n                          if k in _FILTERABLE_COLUMNS and v is not None},\n              "skipped_columns": skipped_cols,\n              "mobilization_buffer_days": mobilization_buffer_days,\n              "earliest_start_monday": earliest_start_monday.isoformat(),\n              "pull_forward_lookup_days": pull_forward_lookup_days}\n\n    # --- 5. SPLIT-ON-GATE branch: run cohort compute twice on disjoint subsets\n    if split_on_gate:\n        gate_keys = [k for k in pt.keys() if k not in ("JOIN", "cx_start")]\n        if split_on_gate not in pt or split_on_gate in ("JOIN", "cx_start"):\n            raise ValueError(\n                "split_on_gate=\'" + str(split_on_gate) +\n                "\' is not a gate in the SLA DAG for project_type \'" + project_type +\n                "\'. Available gates: " + ", ".join(sorted(gate_keys))\n            )\n        gate_spec = pt[split_on_gate]\n        done_rows    = [r for r in rows if _is_done(split_on_gate, gate_spec, r)]\n        missing_rows = [r for r in rows if not _is_done(split_on_gate, gate_spec, r)]\n        config["split_on_gate"] = split_on_gate\n        return {\n            "cohorts": {\n                split_on_gate + "_done":    _compute_cohort(done_rows),\n                split_on_gate + "_missing": _compute_cohort(missing_rows),\n            },\n            "capacity": capacity,\n            "config":   config,\n        }\n\n    # --- 6. Default path: single cohort, flat shape (backwards compatible)\n    cohort = _compute_cohort(rows)\n    return {\n        "summary":            cohort["summary"],\n        "weekly_buckets":     cohort["weekly_buckets"],\n        "committed_sites":    cohort["committed_sites"],\n        "pull_forward_sites": cohort["pull_forward_sites"],\n        "capacity":           capacity,\n        "config":             config,\n    }\n',
#     n.kpi_run_rate_column = 'pj_a_5175_construction_complete_finish'
# RETURN n.label AS label, n.node_id AS node_id;